itens.solucao:
def timecode_para_imagens(texto, fps):
    campos = texto.split(":")
    if len(campos) != 4:
        return None
    for c in campos:
        if not c.isdecimal():
            return None
    hh, mm, ss, ff = (int(c) for c in campos)
    if mm >= 60 or ss >= 60 or ff >= fps:
        return None
    return ((hh * 60 + mm) * 60 + ss) * fps + ff


def imagens_para_timecode(imagem, fps):
    segundos, ff = divmod(imagem, fps)
    hh, resto = divmod(segundos, 3600)
    mm, ss = divmod(resto, 60)
    return f"{hh:02d}:{mm:02d}:{ss:02d}:{ff:02d}"

