itens.solucao:
import re

PADRAO = re.compile(r"(?P<data>\d{4}-\d{2}-\d{2}) (?P<hora>\d{2}:\d{2}:\d{2}) (?P<nivel>[A-Z]+) (?P<mensagem>.*)")

def resumir_registo(linhas):
    contagem = {}
    erros = []
    for linha in linhas:
        m = PADRAO.fullmatch(linha)
        if m is None:
            continue
        nivel = m.group("nivel")
        contagem[nivel] = contagem.get(nivel, 0) + 1
        if nivel == "ERRO":
            erros.append(m.group("mensagem"))
    return contagem, erros

