import io

def media_ficheiro(f):
    valores = []
    for n, linha in enumerate(f, start=1):
        linha = linha.strip()
        if not linha:
            continue
        try:
            valores.append(float(linha))
        except ValueError as erro:
            raise ValueError(f"linha {n} inválida") from erro
    if not valores:
        raise ValueError("ficheiro sem valores")
    return sum(valores) / len(valores)

