class ErroExportacao(Exception):
    """Erro base do módulo de exportação."""


class FormatoNaoSuportado(ErroExportacao):
    pass


class EspacoInsuficiente(ErroExportacao):
    pass


def exportar(nome, formato, mb_necessarios, mb_livres):
    if formato not in ("mp4", "mov", "gif"):
        raise FormatoNaoSuportado(formato)
    if mb_necessarios > mb_livres:
        raise EspacoInsuficiente(f"faltam {mb_necessarios - mb_livres} MB")
    return f"{nome}.{formato}"

