class Timecode:
    def __init__(self, imagem, fps=25):
        self._imagem = imagem
        self._fps = fps

    @classmethod
    def de_texto(cls, texto, fps=25):
        campos = texto.split(":")
        if len(campos) != 4 or not all(c.isdecimal() for c in campos):
            raise ValueError(f"timecode inválido: {texto!r}")
        hh, mm, ss, ff = (int(c) for c in campos)
        if mm >= 60 or ss >= 60 or ff >= fps:
            raise ValueError(f"timecode inválido: {texto!r}")
        return cls(((hh * 60 + mm) * 60 + ss) * fps + ff, fps)

    @property
    def horas(self):
        return self._imagem // self._fps // 3600

    @property
    def minutos(self):
        return self._imagem // self._fps // 60 % 60

    @property
    def segundos(self):
        return self._imagem // self._fps % 60

    @property
    def imagem_no_segundo(self):
        return self._imagem % self._fps

    def somar(self, imagens):
        return Timecode(self._imagem + imagens, self._fps)

    def __str__(self):
        return f"{self.horas:02d}:{self.minutos:02d}:{self.segundos:02d}:{self.imagem_no_segundo:02d}"

    def __repr__(self):
        return f"Timecode({self._imagem}, {self._fps})"

