import math

class Vetor:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __repr__(self):
        return f"Vetor({self.x}, {self.y})"

    def __add__(self, outro):
        if not isinstance(outro, Vetor):
            return NotImplemented
        return Vetor(self.x + outro.x, self.y + outro.y)

    def __eq__(self, outro):
        return isinstance(outro, Vetor) and (self.x, self.y) == (outro.x, outro.y)

    def __mul__(self, k):
        return Vetor(self.x * k, self.y * k)

    __rmul__ = __mul__

    def __neg__(self):
        return Vetor(-self.x, -self.y)

    def __abs__(self):
        return math.hypot(self.x, self.y)

    def __matmul__(self, outro):
        return self.x * outro.x + self.y * outro.y

    def __bool__(self):
        return self.x != 0 or self.y != 0

    def __hash__(self):
        return hash((self.x, self.y))

