from functools import total_ordering

@total_ordering
class Dinheiro:
    def __init__(self, centimos, moeda="EUR"):
        self.centimos = centimos
        self.moeda = moeda

    def _mesma(self, outro):
        if outro.moeda != self.moeda:
            raise ValueError("moedas diferentes")

    def __add__(self, outro):
        if not isinstance(outro, Dinheiro):
            return NotImplemented
        self._mesma(outro)
        return Dinheiro(self.centimos + outro.centimos, self.moeda)

    def __radd__(self, outro):
        if outro == 0:
            return self
        return NotImplemented

    def __sub__(self, outro):
        if not isinstance(outro, Dinheiro):
            return NotImplemented
        self._mesma(outro)
        return Dinheiro(self.centimos - outro.centimos, self.moeda)

    def __mul__(self, k):
        if not isinstance(k, int):
            return NotImplemented
        return Dinheiro(self.centimos * k, self.moeda)

    __rmul__ = __mul__

    def __eq__(self, outro):
        return isinstance(outro, Dinheiro) and (self.centimos, self.moeda) == (outro.centimos, outro.moeda)

    def __lt__(self, outro):
        self._mesma(outro)
        return self.centimos < outro.centimos

    def __hash__(self):
        return hash((self.centimos, self.moeda))

    def __str__(self):
        simbolo = "€" if self.moeda == "EUR" else self.moeda
        return f"{self.centimos // 100},{self.centimos % 100:02d} {simbolo}"

