import functools
from typing import get_type_hints

def verificar_retorno(funcao):
    tipo = get_type_hints(funcao).get("return")

    @functools.wraps(funcao)
    def envolvente(*args, **kwargs):
        resultado = funcao(*args, **kwargs)
        if tipo is not None and not isinstance(resultado, tipo):
            raise TypeError(f"{funcao.__name__} devolveu {type(resultado).__name__}, esperado {tipo.__name__}")
        return resultado
    return envolvente

