    id: int
    titulo: str
    duracao: int
    ano: int

class RepositorioVideos:
    def __init__(self, bd):
        self.bd = bd
        self.bd.execute("""CREATE TABLE IF NOT EXISTS video (
            id INTEGER PRIMARY KEY, titulo TEXT NOT NULL,
            duracao INTEGER NOT NULL, ano INTEGER)""")

    @staticmethod
    def _para_video(linha):
        return Video(*linha) if linha else None

    def adicionar(self, titulo, duracao, ano):
        with self.bd:
            cur = self.bd.execute("INSERT INTO video (titulo, duracao, ano) VALUES (?, ?, ?)", (titulo, duracao, ano))
        return Video(cur.lastrowid, titulo, duracao, ano)

    def obter(self, id_):
        linha = self.bd.execute("SELECT id, titulo, duracao, ano FROM video WHERE id = ?", (id_,)).fetchone()
        return self._para_video(linha)

    def por_ano(self, ano):
        linhas = self.bd.execute("SELECT id, titulo, duracao, ano FROM video WHERE ano = ? ORDER BY titulo", (ano,))
        return [self._para_video(l) for l in linhas]

    def atualizar_duracao(self, id_, duracao):
        with self.bd:
            self.bd.execute("UPDATE video SET duracao = ? WHERE id = ?", (duracao, id_))

