import queue

SENTINELA = None

def produzir(fila, pedidos, n_consumidores):
    for p in pedidos:
        fila.put(p)
    for _ in range(n_consumidores):
        fila.put(SENTINELA)

def consumir(fila, nome):
    feitos = []
    while (p := fila.get()) is not SENTINELA:
        feitos.append(p)
    return feitos

def processar(pedidos, n):
    fila = queue.Queue()
    produzir(fila, pedidos, n)
    ativos = [f"c{i}" for i in range(1, n + 1)]
    quem = {}
    while ativos:
        for nome in list(ativos):
            p = fila.get()
            if p is SENTINELA:
                ativos.remove(nome)
            else:
                quem[p] = nome
    return quem

