    VIDEO = "vídeo"
    AUDIO = "áudio"

EXTENSOES = {".jpg": Tipo.IMAGEM, ".jpeg": Tipo.IMAGEM, ".png": Tipo.IMAGEM,
             ".gif": Tipo.IMAGEM, ".mp4": Tipo.VIDEO, ".mov": Tipo.VIDEO,
             ".mp3": Tipo.AUDIO, ".wav": Tipo.AUDIO}
ASSINATURAS = {b"\x89PNG\r\n\x1a\n": Tipo.IMAGEM, b"\xff\xd8\xff": Tipo.IMAGEM,
               b"GIF8": Tipo.IMAGEM}

def detetar(nome, inicio):
    for assinatura, tipo in ASSINATURAS.items():
        if inicio.startswith(assinatura):
            return tipo
    _, ponto, ext = nome.rpartition(".")
    if not ponto:
        return None
    return EXTENSOES.get("." + ext.lower())

