import hashlib

def duplicados(ficheiros):
    por_tamanho = {}
    for caminho, conteudo in ficheiros.items():
        por_tamanho.setdefault(len(conteudo), []).append(caminho)
    grupos = []
    for caminhos in por_tamanho.values():
        if len(caminhos) < 2:
            continue
        por_resumo = {}
        for c in caminhos:
            resumo = hashlib.sha256(ficheiros[c]).hexdigest()
            por_resumo.setdefault(resumo, []).append(c)
        grupos.extend(sorted(g) for g in por_resumo.values() if len(g) > 1)
    return sorted(grupos)

