import io

def duracao_em_segundos(texto):
    """Converte \"m:ss\" em segundos."""
    minutos, sep, segundos = texto.strip().partition(":")
    if not sep or not minutos.isdecimal() or not segundos.isdecimal() or len(segundos) != 2:
        raise ValueError(f"duração inválida: {texto!r}")
    m, s = int(minutos), int(segundos)
    if s >= 60:
        raise ValueError(f"segundos devem ser menores do que 60: {texto!r}")
    return m * 60 + s


def ler_faixas(f):
    """Devolve (faixas, erros) a partir de um ficheiro CSV já aberto."""
    texto = f.read().removeprefix("\ufeff")
    faixas, erros = [], []
    for n, r in enumerate(csv.DictReader(io.StringIO(texto), delimiter=";"), start=2):
        try:
            segundos = duracao_em_segundos(r["duracao"] or "")
            ano = int(r["ano"])
            if not r["titulo"] or not r["artista"]:
                raise ValueError("título ou artista em falta")
        except ValueError as e:
            erros.append(f"linha {n}: {e}")
            continue
        faixas.append((r["titulo"], r["artista"], segundos, ano))
    return faixas, erros

