class ExcedeDuracao(Exception):
    """A faixa não cabe no alinhamento."""


class Alinhamento:
    """Alinhamento musical de um programa de rádio."""

    def __init__(self, duracao_maxima):
        self.duracao_maxima = duracao_maxima
        self._faixas = []

    @property
    def duracao(self):
        return sum(f.segundos for f in self._faixas)

    def juntar(self, faixa):
        if self.duracao + faixa.segundos > self.duracao_maxima:
            raise ExcedeDuracao(f"{faixa.titulo} excede a duração máxima")
        self._faixas.append(faixa)

    def retirar(self, titulo):
        for f in self._faixas:
            if f.titulo == titulo:
                self._faixas.remove(f)
                return f
        raise KeyError(titulo)

    def __len__(self):
        return len(self._faixas)

    def __iter__(self):
        yield from self._faixas

